 if(typeof b.password!=='string'||b.password.length<8||b.password.length>128||b.password!==b.confirm)return reply({error:'Use a unique password of at least 8 characters; confirmation must match'},400);
 const salt=randomBytes(16).toString('hex'),hash=scryptSync(b.password,salt,64).toString('hex');const {modified}=await authStore.setJSON('user-'+email,{email,salt,hash},{onlyIfNew:true});
